7	export type EnvironmentSanitizationConfig = {
8	  allowedEnvironmentVariables: string[];
9	  blockedEnvironmentVariables: string[];
10	  enableEnvironmentVariableRedaction: boolean;
11	};
12	
13	export function sanitizeEnvironment(
14	  processEnv: NodeJS.ProcessEnv,
15	  config: EnvironmentSanitizationConfig,
16	): NodeJS.ProcessEnv {
17	  const isStrictSanitization =
18	    !!processEnv['GITHUB_SHA'] || processEnv['SURFACE'] === 'Github';
19	
20	  if (!config.enableEnvironmentVariableRedaction && !isStrictSanitization) {
21	    return { ...processEnv };
22	  }
23	
24	  const results: NodeJS.ProcessEnv = {};
25	
26	  const allowedSet = new Set(
27	    (config.allowedEnvironmentVariables || []).map((k) => k.toUpperCase()),
28	  );
29	  const blockedSet = new Set(
30	    (config.blockedEnvironmentVariables || []).map((k) => k.toUpperCase()),
31	  );
32	
33	  for (const key in processEnv) {
34	    const value = processEnv[key];
35	
36	    if (
37	      !shouldRedactEnvironmentVariable(
38	        key,
39	        value,
40	        allowedSet,
41	        blockedSet,
42	        isStrictSanitization,
43	      )
44	    ) {
45	      results[key] = value;
46	    }
47	  }
48	
49	  return results;
50	}
