111	export const NEVER_ALLOWED_NAME_PATTERNS = [
112	  /TOKEN/i,
113	  /SECRET/i,
114	  /PASSWORD/i,
115	  /PASSWD/i,
116	  /KEY/i,
117	  /AUTH/i,
118	  /CREDENTIAL/i,
119	  /CREDS/i,
120	  /PRIVATE/i,
121	  /CERT/i,
122	] as const;
123	
124	export const NEVER_ALLOWED_VALUE_PATTERNS = [
125	  /-----BEGIN (RSA|OPENSSH|EC|PGP) PRIVATE KEY-----/i,
126	  /-----BEGIN CERTIFICATE-----/i,
127	  // Credentials in URL
128	  /(https?|ftp|smtp):\/\/[^:\s]{1,1024}:[^@\s]{1,1024}@/i,
129	  // GitHub tokens (classic, fine-grained, OAuth, etc.)
130	  /(ghp|gho|ghu|ghs|ghr|github_pat)_[a-zA-Z0-9_]{36,}/i,
131	  // Google API keys
132	  /AIzaSy[a-zA-Z0-9_\\-]{33}/i,
133	  // Amazon AWS Access Key ID
134	  /AKIA[A-Z0-9]{16}/i,
135	  // Generic OAuth/JWT tokens
136	  /eyJ[a-zA-Z0-9_-]{0,10240}\.[a-zA-Z0-9_-]{0,10240}\.[a-zA-Z0-9_-]{0,10240}/i,
137	  // Stripe API keys
138	  /(s|r)k_(live|test)_[0-9a-zA-Z]{24}/i,
139	  // Slack tokens (bot, user, etc.)
140	  /xox[abpr]-[a-zA-Z0-9-]+/i,
141	] as const;
