143	function shouldRedactEnvironmentVariable(
144	  key: string,
145	  value: string | undefined,
146	  allowedSet?: Set<string>,
147	  blockedSet?: Set<string>,
148	  isStrictSanitization = false,
149	): boolean {
150	  key = key.toUpperCase();
151	  value = value?.toUpperCase();
152	
153	  if (key.startsWith('GEMINI_CLI_')) {
154	    return false;
155	  }
156	
157	  if (value) {
158	    for (const pattern of NEVER_ALLOWED_VALUE_PATTERNS) {
159	      if (pattern.test(value)) {
160	        return true;
161	      }
162	    }
163	  }
164	
165	  if (allowedSet?.has(key)) {
166	    return false;
167	  }
168	  if (blockedSet?.has(key)) {
169	    return true;
170	  }
171	
172	  if (ALWAYS_ALLOWED_ENVIRONMENT_VARIABLES.has(key)) {
173	    return false;
174	  }
175	
176	  if (NEVER_ALLOWED_ENVIRONMENT_VARIABLES.has(key)) {
177	    return true;
178	  }
179	
180	  if (isStrictSanitization) {
181	    return true;
182	  }
183	
184	  for (const pattern of NEVER_ALLOWED_NAME_PATTERNS) {
185	    if (pattern.test(key)) {
186	      return true;
187	    }
188	  }
189	
190	  return false;
191	}
